export function createCat3Data(idx: number): CategoryIIIScores {
  // Balanced filter distribution across dataset
  const hasPatents = idx % 2 === 0;
  const hasGrants = idx % 3 === 0 || idx % 5 === 0;
  const hasCitations = idx % 4 !== 0;
  const hasPhd = idx % 2 === 1;
  const numJournals = (idx % 6 === 0) ? 0 : (idx % 3) + 1; // ~83% have >= 1 paper

  const journalTitles = [
    'AI-Based Predictive Analytics for Higher Education Governance',
    'Deep Learning Architectures in Institutional Data Processing',
    'Optimization of Academic Performance Indicators using Neural Networks',
    'Cloud-Native ERP Systems for University Resource Allocation',
    'Sustainable Energy Harvesting for Smart Campus Sensor Networks',
    'Novel Synthesis of Nanomaterials for Energy Storage Applications',
    'Biochemical Characterization of Bioactive Secondary Metabolites',
    'Mathematical Modeling of Complex Institutional Workflows',
  ];

  const journalNames = [
    'IEEE Transactions on Knowledge and Data Engineering',
    'Nature Scientific Reports',
    'Springer Journal of Academic Analytics',
    'Elsevier Applied Soft Computing',
    'ACM Transactions on Computer Systems',
    'Journal of Cleaner Production',
    'Biotechnology and Applied Biochemistry',
    'Journal of Computational and Applied Mathematics',
  ];

  const journalEntries = [];
  for (let j = 0; j < numJournals; j++) {
    const title = journalTitles[(idx + j) % journalTitles.length];
    const journalName = journalNames[(idx + j) % journalNames.length];
    const indexing = j % 2 === 0 ? ('SCI' as const) : ('Scopus' as const);
    // Q1 papers given to ~67% of faculty (idx % 3 !== 0)
    const quartile = (j === 0 && idx % 3 !== 0) ? ('Q1' as const) : j === 1 ? ('Q2' as const) : ('Q3' as const);

    journalEntries.push({
      id: `jrn-${idx}-${j}`,
      title,
      journalName,
      indexing,
      quartile,
      authorPosition: j === 0 ? ('First' as const) : ('Corresponding' as const),
      numberOfAuthors: 3,
      doiLink: `https://doi.org/10.1016/j.jss.2025.${1000 + idx + j}`,
      proofUrl: 'https://scopus.com/inward/record.uri?eid=2-s2.0-85123456789',
      calculatedScore: quartile === 'Q1' ? 30 : 20,
    });
  }

  const citationsScopus = hasCitations
    ? [
        {
          id: `cit-${idx}-1`,
          paperTitle: journalTitles[idx % journalTitles.length],
          journal: journalNames[idx % journalNames.length],
          year: 2024,
          citationCount: (idx % 15) + 5,
          selfCitationsRemoved: true,
          hasInstitutionalAffiliation: true,
          proofUrl: 'https://scopus.com/citations/demo.pdf',
        },
      ]
    : [];

  const citationsQ1 = hasCitations
    ? [
        {
          id: `citq1-${idx}-1`,
          paperTitle: journalTitles[idx % journalTitles.length],
          journal: 'Nature Scientific Reports',
          year: 2024,
          quartile: 'Q1' as const,
          q1CitationCount: (idx % 10) + 3,
          hasInstitutionalAffiliation: true,
          proofUrl: 'https://nature.com/articles/demo.pdf',
        },
      ]
    : [];

  const patents = hasPatents
    ? [
        {
          id: `pat-${idx}-1`,
          title: `Automated AI-Driven Academic Evaluation System (App #${202541090000 + idx})`,
          appNumber: `20254109${1000 + idx} A`,
          status: idx % 4 === 0 ? ('Granted' as const) : ('Published' as const),
          inventorPosition: 'First Inventor',
          institutionalAffiliation: true,
          proofUrl: 'https://ipindia.gov.in/patents/demo.pdf',
        },
      ]
    : [];

  const fundedProjects = hasGrants
    ? [
        {
          id: `fp-${idx}-1`,
          projectTitle: `Development of High-Efficiency AI Analytics Platform (Grant #${idx + 101})`,
          agency: idx % 2 === 0 ? 'DST / SERB' : 'AICTE RPS',
          role: 'PI' as const,
          status: 'Sanctioned' as const,
          amountSanctioned: (idx % 5 + 1) * 350000,
          sanctionNoDate: 'SERB/2025/00123',
          duration: '2 Years',
          institutionalApproval: true,
          proofUrl: 'https://serb.gov.in/grants/demo.pdf',
        },
      ]
    : [];

  const phdSupervisionTable = hasPhd
    ? [
        {
          id: `phd-${idx}-1`,
          scholarName: `Research Scholar ${idx + 1} (SRMIST)`,
          researchTitle: `Advanced Optimization in ${journalNames[idx % journalNames.length]}`,
          role: 'Guide' as const,
          status: 'Registered' as const,
          mode: 'Full-Time' as const,
          yearRegGrad: '2022',
          yearCompletion: '2026',
          proofUrl: 'https://srmist.edu.in/phd/demo.pdf',
        },
      ]
    : [];

  const cat3ScoreSum = 60 + journalEntries.length * 20 + (hasPatents ? 25 : 0) + (hasGrants ? 30 : 0);

  return {
    journals: journalEntries,
    citationsScopus,
    citationsQ1,
    consultancy: [],
    patents,
    phdSupervisionTable,
    researchAwardsTable: [],
    fundedProjects,
    industryUseCases: [],
    totalSelfScore: Math.min(cat3ScoreSum, 190),
    totalHodScore: Math.min(cat3ScoreSum, 190),
  };
}

