// Post-process SEED_APPRAISALS to ensure 100% complete demo data across all 85 faculty profiles
for (let idx = 0; idx < SEED_APPRAISALS.length; idx++) {
  const rec = SEED_APPRAISALS[idx];
  const cat1 = createCat1Data(idx);
  const cat2 = createCat2Data(idx);
  const cat3 = createCat3Data(idx);

  const totalScore = Math.min(cat1.totalHodScore + cat2.totalHodScore + cat3.totalHodScore, 350);
  const grade = totalScore >= 310 ? 'Grade A' : totalScore >= 265 ? 'Grade B' : 'Grade C';
  const statusList: ('HOI_APPROVED' | 'HOD_APPROVED' | 'SUBMITTED' | 'DRAFT')[] = [
    'HOI_APPROVED',
    'HOD_APPROVED',
    'SUBMITTED',
    'DRAFT',
  ];
  const assignedStatus = statusList[idx % 4];

  rec.cat1 = cat1;
  rec.cat2 = cat2;
  rec.cat3 = cat3;
  rec.selfScoreTotal = totalScore;
  rec.hodScoreTotal = totalScore;
  rec.hoiScoreTotal = totalScore;
  rec.grade = grade;
  rec.status = assignedStatus;
}

